UPDATE doc_library_node
SET owner_user_id = #{ownerUserId},
    parent_id = NULL,
    deleted = #{deleted},
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND tenant_id = #{tenantId}

UPDATE doc_drive_item
SET owner_user_id = #{ownerUserId},
    folder_id = NULL,
    deleted = #{deleted},
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND tenant_id = #{tenantId}

UPDATE doc_library_node
SET deleted = 1,
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND deleted = 0

UPDATE doc_drive_item
SET deleted = 1,
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND deleted = 0
